      const winningTeam = counts[0] < counts[1] ? 0 : 1;
      return { losingTeam: 1 - winningTeam, winningTeam };
    }
    if (validTeam(this.engine?.leader)) return { losingTeam: 1 - this.engine.leader, winningTeam: this.engine.leader };
